import { z } from 'zod';
import { CompilationResult, ProcessedSection, Usage, ShoppingListItem, CompositeItem, Warning } from '@gram-lang/kitchen';
import { Meta } from '@gram-lang/parser';
export { NUTRIENTS, NutrientDef, NutrientKey, NutrientUnit } from './nutrients.js';

declare const AnalyzerOptionsSchema: z.ZodObject<{
    enableMassStandardization: z.ZodOptional<z.ZodBoolean>;
    enableYieldCalculation: z.ZodOptional<z.ZodBoolean>;
    enableNutritionalEstimation: z.ZodOptional<z.ZodBoolean>;
    enableBakersMath: z.ZodOptional<z.ZodBoolean>;
    bakersReference: z.ZodOptional<z.ZodString>;
    portions: z.ZodOptional<z.ZodNumber>;
    lang: z.ZodOptional<z.ZodString>;
}, z.core.$strip>;
declare const NutritionSchema: z.ZodObject<{
    calories: z.ZodNumber;
    fat: z.ZodNumber;
    carbs: z.ZodNumber;
    protein: z.ZodNumber;
    sat_fat: z.ZodOptional<z.ZodNumber>;
    mono_fat: z.ZodOptional<z.ZodNumber>;
    poly_fat: z.ZodOptional<z.ZodNumber>;
    sugar: z.ZodOptional<z.ZodNumber>;
    fiber: z.ZodOptional<z.ZodNumber>;
    sodium: z.ZodOptional<z.ZodNumber>;
    alcohol: z.ZodOptional<z.ZodNumber>;
}, z.core.$strip>;
/**
 * One nutrient profile: per 100 g for a database entry, per whole recipe /
 * portion / 100 g for an analyzed one. Both sides share this shape by
 * construction — the aggregation multiplies the former into the latter.
 */
type Macros = z.infer<typeof NutritionSchema>;
declare const IngredientDataSchema: z.ZodObject<{
    name: z.ZodString;
    physical: z.ZodOptional<z.ZodObject<{
        density: z.ZodOptional<z.ZodNumber>;
        yield: z.ZodOptional<z.ZodNumber>;
        unit_weight: z.ZodOptional<z.ZodNumber>;
    }, z.core.$strip>>;
    nutrition: z.ZodOptional<z.ZodObject<{
        calories: z.ZodNumber;
        fat: z.ZodNumber;
        carbs: z.ZodNumber;
        protein: z.ZodNumber;
        sat_fat: z.ZodOptional<z.ZodNumber>;
        mono_fat: z.ZodOptional<z.ZodNumber>;
        poly_fat: z.ZodOptional<z.ZodNumber>;
        sugar: z.ZodOptional<z.ZodNumber>;
        fiber: z.ZodOptional<z.ZodNumber>;
        sodium: z.ZodOptional<z.ZodNumber>;
        alcohol: z.ZodOptional<z.ZodNumber>;
    }, z.core.$strip>>;
    aliases: z.ZodOptional<z.ZodArray<z.ZodString>>;
    tags: z.ZodOptional<z.ZodArray<z.ZodString>>;
    category: z.ZodOptional<z.ZodString>;
}, z.core.$strip>;

type AnalyzerOptions = z.infer<typeof AnalyzerOptionsSchema>;

interface MassMetrics {
    totalMass: number;
    massStatus: "precise" | "estimated" | "incomplete";
    missingMassIngredients: string[];
}
interface NutritionMetrics {
    /** The whole recipe, at the quantities it was compiled/scaled to. */
    total: Macros;
    /** Present whenever the portion count is known — see NutritionMetrics.portions. */
    perPortion?: Macros;
    /**
     * Per 100 g of the ingredients that contributed macros (see `basis`).
     * Independent of `portions`, so an unportioned recipe still gets a
     * standardized basis.
     *
     * Gram models no cooking loss — no evaporation, no bake loss — so this is
     * per 100 g of the *raw assembled* mixture, which understates a reduced
     * stew or a baked loaf against a finished-product label.
     */
    per100g?: Macros;
    /** The divisor `perPortion` was derived with, once resolved. */
    portions?: number;
    /**
     * The denominator behind `per100g`, exposed so a UI can caveat the figure
     * without recomputing it: `massStatus: "incomplete"` means the mass is a
     * lower bound, and the density therefore an over-estimate.
     */
    basis?: {
        mass: number;
        massStatus?: MassMetrics["massStatus"];
    };
    isEstimate: boolean;
    coverage: number;
    warnings?: Warning[];
}
type IngredientData = z.infer<typeof IngredientDataSchema>;
interface AnalyzedUsage extends Usage {
    normalizedMass?: number;
    conversionMethod?: "physical" | "density" | "unit_weight" | "default" | "explicit" | "estimate" | "relative";
    isEstimate?: boolean;
    purchasingMass?: number;
    bakersPercentage?: number;
}
interface AnalyzedSection extends ProcessedSection {
    ingredients: AnalyzedUsage[];
    cookware: AnalyzedUsage[];
    metrics?: MassMetrics;
}
interface AnalyzedCompilationResult extends Omit<CompilationResult, "sections" | "metrics"> {
    sections: AnalyzedSection[];
    shopping_list: (AnalyzedUsage | ShoppingListItem | CompositeItem)[];
    metrics: CompilationResult["metrics"] & MassMetrics & {
        nutrition?: NutritionMetrics;
    };
}
interface AnalysisResult {
    result: AnalyzedCompilationResult;
    missingIngredients: string[];
}

/**
 * Resolves the usage that actually contributes to a recipe's totals, or null
 * if the item contributes nothing.
 *
 * Two rules, both of which used to be implemented twice — once in `metrics.ts`
 * for the mass totals and once in `nutrition.ts` for the macro totals, with
 * different levels of defensiveness (the nutrition copy cast `options[0]`
 * blind). Having the two totals disagree about what counts as "in" the recipe
 * is what makes a derived figure like kcal per 100 g meaningless, so they read
 * the same rules from here:
 *
 * - An ingredient marked optional (`?`) is excluded, which keeps every total on
 *   the same conservative baseline: the dish as it is when you skip the
 *   garnish.
 * - An alternative group ("egg OR tofu") has no single value of its own, only
 *   whichever option is actually used, so it resolves to the first (preferred)
 *   option. That option can itself be optional, hence the second check.
 */
declare function resolveContributingUsage(item: AnalyzedUsage): AnalyzedUsage | null;

declare function getIngredientData(name: string, database: Record<string, IngredientData>): IngredientData | null;
/**
 * Resolves an ingredient name/alias to its canonical database key (e.g. "beurre" -> "butter"),
 * so that shopping-list aggregation can group aliased ingredients under one entry.
 * Falls back to `slugify(name)` when the ingredient isn't found in the database.
 */
declare function resolveCanonicalId(name: string, database: Record<string, IngredientData>): string;

/**
 * Mass Normalization Module
 *
 * Responsible for converting physical mass units into a standard Gram unit (g).
 */
interface ConversionResult {
    mass: number;
    method: "physical" | "density" | "unit_weight" | "default" | "explicit";
}
/**
 * Converts a value between two unit strings. Same-family conversions
 * (mass-to-mass, or volume-to-volume) use the UNIT_CONVERSIONS table alone.
 * Crossing families (mass <-> volume) additionally requires a `density`
 * (g/mL) — pass the ingredient's resolved density (see
 * `resolveIngredientDensity`) to bridge it. Without one, cross-family
 * conversions return null rather than guess — callers should surface that as
 * a distinct error.
 *
 * `lang` (the recipe's own language, e.g. from frontmatter/config) resolves
 * `fromUnit`/`toUnit` against that language's dictionary first — see
 * `normalizeUnit`'s own doc comment for why this matters when an alias
 * collides across languages.
 */
declare function convertUnit(value: number, fromUnit: string, toUnit: string, density?: number, lang?: string): number | null;
interface DensityResolution {
    density: number;
    isEstimate: boolean;
}
/**
 * Resolves an ingredient's density (g/mL), checking recipe-level overrides
 * (frontmatter `densities:`, see `parseDensityOverrides`) before falling back
 * to the ingredient database. Shared by `standardizeMass` and by
 * density-aware unit conversion (e.g. reverse scaling across mass <-> volume).
 */
declare function resolveIngredientDensity(ingredientName: string, database: Record<string, IngredientData>, overrides?: Record<string, number>): DensityResolution | null;
/**
 * Parses recipe-level density overrides from frontmatter (e.g.
 * `densities: [water:1.0]`) into a slug -> density (g/mL) map.
 */
declare function parseDensityOverrides(meta: Meta): Record<string, number>;
declare function standardizeMass(amount: number, unit: string, database: Record<string, IngredientData>, ingredientName?: string, overrides?: Record<string, number>, lang?: string): (ConversionResult & {
    isEstimate: boolean;
}) | null;
interface YieldedMass {
    normalizedMass: number;
    purchasingMass?: number;
}
/**
 * Applies the yield (waste factor) to a standardized mass, distinguishing between:
 * - `unit_weight` conversions (e.g. "1 avocado"), which represent the whole purchased
 *   unit — i.e. Gross Mass. The recipe/nutrition-facing Net Mass is derived forward
 *   by multiplying by yield.
 * - Any other conversion (explicit grams, volume+density), which represents what the
 *   recipe author put in the bowl — i.e. Net Mass. The purchasing Gross Mass is
 *   derived backward by dividing by yield.
 */
declare function applyYield(mass: number, method: ConversionResult["method"], yieldFactor?: number): YieldedMass;

type NutritionItem = AnalyzedUsage & {
    usage?: NutritionItem[];
};
declare function calculateNutrition(ingredients: NutritionItem[], database: Record<string, IngredientData>, portions?: number, massStatus?: MassMetrics["massStatus"]): NutritionMetrics;

/**
 * Calculates mass metrics (totals, precision status, and missing data warnings)
 * for a list of ingredient usages by querying their normalized masses.
 */
declare function calculateMassMetrics(ingredients: AnalyzedUsage[]): MassMetrics;

interface DiffableModuleInfo {
    uri: string;
    binding: string;
    scaleFactor: number;
}
interface DiffableSection extends ProcessedSection {
    module?: unknown;
}
interface DiffableCompilationResult extends CompilationResult {
    sections: DiffableSection[];
    modules?: DiffableModuleInfo[];
}
interface MetaDelta {
    field: string;
    from: unknown;
    to: unknown;
}
interface IngredientDelta {
    id: string;
    name: string;
    change: "added" | "removed" | "changed";
    fromQty?: number;
    fromUnit?: string | null;
    toQty?: number;
    toUnit?: string | null;
    percentChange?: number;
}
interface PrepDelta {
    id: string;
    name: string;
    section: string | null;
    from: string | null;
    to: string | null;
}
interface TimingDelta {
    field: "totalTime" | "idleTime" | "activeTime" | "preparationTime";
    from: number;
    to: number;
}
interface SectionDelta {
    change: "added" | "removed" | "changed";
    title: string | null;
    fromStepCount?: number;
    toStepCount?: number;
}
interface TemperatureDelta {
    section: string | null;
    name?: string;
    change: "added" | "removed" | "changed";
    from?: {
        value: number;
        unit: string;
        range?: {
            min: number;
            max: number;
        };
    };
    to?: {
        value: number;
        unit: string;
        range?: {
            min: number;
            max: number;
        };
    };
}
interface TimerDelta {
    section: string | null;
    name?: string;
    change: "added" | "removed" | "changed";
    from?: string;
    to?: string;
}
interface ModuleDelta {
    uri: string;
    change: "added" | "removed" | "changed";
    fromBinding?: string;
    toBinding?: string;
    fromFactor?: number;
    toFactor?: number;
}
interface DiffResult {
    hasChanges: boolean;
    titleChanged: boolean;
    fromTitle: string | null;
    toTitle: string | null;
    meta: MetaDelta[];
    ingredients: IngredientDelta[];
    preparations: PrepDelta[];
    timings: TimingDelta[];
    sections: SectionDelta[];
    temperatures: TemperatureDelta[];
    timers: TimerDelta[];
    modules: ModuleDelta[];
}
declare function diffRecipes(a: DiffableCompilationResult, b: DiffableCompilationResult): DiffResult;

type ShoppingListEntry = CompilationResult["shopping_list"][number];
/**
 * Re-groups the shopping list produced by `@gram-lang/kitchen` (which groups purely by
 * raw id + unit, with no knowledge of the ingredient database) by CANONICAL id,
 * merging aliased ingredients (e.g. "beurre"/"butter") and cross-unit entries
 * (e.g. "100g" + "1 cup") into a single line whenever every contributing entry
 * already has a resolved `normalizedMass` (in grams).
 *
 * When a group can't be fully resolved to a mass (e.g. one entry has no density/
 * unit_weight available), the entries are left separate but renamed to the
 * canonical id/name and flagged `multiUnit: true`, so renderers can still group
 * them visually. Composite and alternative entries pass through untouched —
 * their own MAX/SUM and first-choice resolution rules are handled upstream by
 * `@gram-lang/kitchen`.
 */
declare function aggregateShoppingList(shoppingList: ShoppingListEntry[], database: Record<string, IngredientData>): ShoppingListEntry[];

interface IngredientValidationIssue {
    key: string;
    message: string;
}
interface IngredientValidationResult {
    data: Record<string, IngredientData>;
    rejected: IngredientValidationIssue[];
}
/**
 * Validates a raw ingredient database entry-by-entry rather than
 * all-or-nothing: one malformed entry (a typo, a bad density value) no
 * longer prevents every other valid ingredient from loading. Callers that
 * need to report exactly what's wrong (e.g. `gram db validate`) can surface
 * `rejected`; callers that just need a usable database (e.g. compiling a
 * recipe) can use `data` and warn.
 */
declare function validateIngredientDatabase(rawDb: unknown): IngredientValidationResult;
/**
 * Main entry point for recipe physical analysis.
 * Takes a pure structural CompilationResult and a macro-ingredient database,
 * then enriches it with calculated masses, yields, and nutritional profiles.
 */
declare function analyze(result: CompilationResult, database: Record<string, IngredientData>, options?: AnalyzerOptions): AnalysisResult;

export { type AnalysisResult, type AnalyzedCompilationResult, type AnalyzedSection, type AnalyzedUsage, type AnalyzerOptions, AnalyzerOptionsSchema, type DensityResolution, type DiffResult, type IngredientData, IngredientDataSchema, type IngredientDelta, type IngredientValidationIssue, type IngredientValidationResult, type Macros, type MassMetrics, type MetaDelta, type ModuleDelta, type NutritionItem, type NutritionMetrics, NutritionSchema, type PrepDelta, type SectionDelta, type TemperatureDelta, type TimerDelta, type TimingDelta, type YieldedMass, aggregateShoppingList, analyze, applyYield, calculateMassMetrics, calculateNutrition, convertUnit, diffRecipes, getIngredientData, parseDensityOverrides, resolveCanonicalId, resolveContributingUsage, resolveIngredientDensity, standardizeMass, validateIngredientDatabase };
